// ----- chests (08r): painted pixel art, the lid is the top ~40 % (the reveal lifts it off) -----
// three shop chests grow richer: plain planks → iron-bound → royal velvet and gold; the tower crate and the pet basket look different on purpose
function chestArt(kind){const W=36,H=32;return artSprite(W,H,g=>{const R=(x,y,w,h,c)=>{g.fillStyle=c;g.fillRect(x,y,w,h);},P=(x,y,c)=>R(x,y,1,1,c);
  const lidRow=y=>y===4?[7,29]:y===5?[5,31]:y===6?[4,32]:[3,33];
  const box=(lid,lidHi,lidDk,body,bodyDk,seam)=>{for(let y=4;y<14;y++){const [a,b]=lidRow(y);R(a,y,b-a,1,y<6?lidHi:y>11?lidDk:lid);}R(3,13,30,1,seam);for(let y=14;y<29;y++)R(3,y,30,1,y>26?bodyDk:body);R(4,29,28,1,bodyDk);};
  const planks=(c,step)=>{for(let x=3+step;x<33;x+=step){for(let y=6;y<13;y++)P(x,y,c);for(let y=14;y<28;y++)P(x,y,c);}};
  if(kind==='wood'){box('#8a5a32','#b07a48','#6a4424','#7a4e2a','#5a3a1e','#3a2412');planks('#5e3c1e',6);
    for(const bx of [7,27]){R(bx,5,2,24,'#5a5a66');R(bx,5,1,24,'#7a7a88');}
    R(15,11,6,7,'#6a6a78');R(16,12,4,5,'#8a8a98');R(17,14,2,2,'#1a1420');P(18,16,'#1a1420');}
  else if(kind==='iron'){box('#5a3a24','#7a5232','#3e2818','#4e3220','#34200f','#1e140c');planks('#3e2818',5);
    for(const bx of [4,15,27]){const w=bx===15?6:5;R(bx,5,w,25,'#5a6070');R(bx,5,w,1,'#aab0c4');R(bx,5,1,25,'#8a90a4');for(let y=8;y<29;y+=5){P(bx+1,y,'#cfd4e8');P(bx+w-2,y,'#cfd4e8');}}
    R(3,20,30,3,'#5a6070');R(3,20,30,1,'#aab0c4');
    R(14,10,8,9,'#2a2c38');R(15,11,6,7,'#9aa0b4');R(15,11,6,1,'#e8eef8');R(17,13,2,3,'#14101c');P(17,16,'#14101c');P(18,16,'#14101c');}
  else if(kind==='gold'){box('#6a2a8a','#8a3ab0','#4a1a6a','#5a2278','#3a1050','#2a0a3a');
    const gd='#f6c744',gl='#fff2a0',gk='#a8781a';
    for(let y=4;y<14;y++){const [a,b]=lidRow(y);P(a,y,gd);P(b-1,y,gd);}R(7,4,22,1,gl);R(3,12,30,1,gd);R(3,14,30,2,gd);R(3,14,30,1,gl);R(3,27,30,2,gd);R(3,14,2,15,gd);R(31,14,2,15,gd);R(3,14,1,15,gl);
    for(const [x,y] of [[3,14],[29,14],[3,25],[29,25]]){R(x,y,4,4,gd);P(x+1,y+1,gl);P(x+2,y+2,gk);}
    R(12,9,12,3,gd);R(12,9,12,1,gl);R(12,11,12,1,gk);for(const [x,t] of [[12,6],[15,7],[17,5],[18,5],[20,7],[23,6]])R(x,t,1,9-t,gd);P(12,5,'#e8453c');P(23,5,'#e8453c');R(17,4,2,1,'#7fd0ff');P(15,6,gl);P(20,6,gl);P(14,10,'#e8453c');P(18,10,'#4aa3e8');P(21,10,'#e8453c');
    R(14,16,8,9,gk);R(15,17,6,7,gd);R(15,17,6,1,gl);R(16,19,4,3,'#c8203a');R(16,19,2,1,'#ff8aa0');P(18,22,'#7a1020');
    for(const [x,y] of [[8,20],[26,22],[10,25],[24,18]])P(x,y,'#b070e0');}
  else if(kind==='tower'){// a builder's crate: flat slatted lid, cross brace, a blueprint roll and a cog
    const wd='#a07a4a',wl='#c89a62',wk='#6a4a2a',br='#7a5632';
    R(3,7,30,6,wd);R(3,7,30,1,wl);for(let x=3;x<33;x+=7)R(x,7,1,6,wk);R(3,12,30,1,wk);R(2,6,32,1,wk);
    R(3,14,30,15,wd);for(let y=14;y<29;y+=5)R(3,y,30,1,wk);R(3,14,2,15,br);R(31,14,2,15,br);
    for(let i=0;i<14;i++){R(5+i*2,15+i,2,1,br);R(29-i*2,15+i,2,1,br);}
    R(4,29,28,1,wk);
    R(20,2,12,4,'#4a7ad8');R(20,2,12,1,'#8ab4ff');R(31,2,1,4,'#2a4a98');for(const x of [22,25,28])P(x,4,'#e8f4ff');R(19,3,1,2,'#2a4a98');
    const cx=18,cy=21;for(let k=0;k<8;k++){const a=k/8*6.283;R(Math.round(cx-1+Math.cos(a)*5),Math.round(cy-1+Math.sin(a)*5),2,2,'#2a8a8a');}for(let y=-4;y<=4;y++)for(let x=-4;x<=4;x++){const d=Math.hypot(x+.5,y+.5);if(d<4.6)P(cx+x,cy+y,d<2?'#14404a':d<3.4?'#7af0d0':'#3ab0a0');}}
  else if(kind==='pet'){// a woven basket with a domed lid, a ribbon and a paw print
    const wk=['#c8964a','#a8783a','#8a5a2a'];
    for(let y=5;y<12;y++){const hw=Math.round(12*Math.sqrt(Math.max(0,1-Math.pow((11.5-y)/7.5,2))));for(let x=18-hw;x<18+hw;x++)P(x,y,y===5?'#d8a860':wk[((x>>1)+(y>>1))%2?0:1]);}
    R(3,11,30,3,'#8a5a2a');R(3,11,30,1,'#e0b070');R(3,13,30,1,'#5a3a18');
    for(let y=14;y<29;y++){const t=(y-14)/15,hw=Math.round(14-t*t*4);for(let x=18-hw;x<18+hw;x++)P(x,y,y%3===0?wk[2]:wk[((x>>1)+(y))%2?0:1]);}
    R(6,28,24,1,'#6a4220');
    R(15,4,6,3,'#e8607a');R(12,3,4,3,'#e8607a');R(20,3,4,3,'#e8607a');R(12,3,4,1,'#ff9ab0');R(20,3,4,1,'#ff9ab0');R(17,4,2,2,'#b83a5a');
    const px=18,py=21;R(px-2,py,4,3,'#f4ecd8');R(px-3,py+1,6,1,'#f4ecd8');for(const [dx,dy] of [[-4,-2],[-2,-3],[1,-3],[3,-2]])R(px+dx,py+dy,1,2,'#f4ecd8');}
 });}
