const SPR={enemy:{},boss:{},hero:{},icon:{},prop:{},misc:{},elite:{},tower:{},pet:{}};
function initSprites(){
  ICONS.coin.pal=Object.assign({Y:'#c28a10'},ICONS.coin.pal);
  for(const id in ICONS)SPR.icon[id]=buildSprite(ICONS[id].rows,{mirror:false,pal:ICONS[id].pal,shade:false});
  for(const k in CHEST_PAL)SPR.icon['chest_'+k]=chestArt(k);
  for(const id in ENEMY_DEFS)SPR.enemy[id]=buildSprite(ENEMY_DEFS[id].rows,{pal:ENEMY_DEFS[id].pal});
  for(const id in BOSS_DEFS)SPR.boss[id]=buildSprite(BOSS_DEFS[id].rows,{pal:BOSS_DEFS[id].pal,scale:2});
  for(const id in HEROES)SPR.hero[id]=buildSprite(HEROES[id].rows,{pal:HEROES[id].pal});
  SPR.misc.chest=buildSprite(['.nnnnn','nnnnnn','yyyyyy','nnnnny','nbbbbb','nbbbbb'].map(r=>r),{pal:{b:'#5a3a22'}});
  SPR.misc.shot=buildSprite(['.rr','rrr','rrr','.rr'],{pal:{r:'#ff5a7a'},outline:false,shade:false});
  for(const k in TOWERS)SPR.tower[k]=buildSprite(TOWERS[k].rows,{pal:TOWERS[k].pal});
  for(const k in PETS)SPR.pet[k]=buildSprite(PETS[k].rows,{pal:PETS[k].pal});
  SPR.misc.xbow=buildSprite(['....n..','....kn.','....kn.','ddnnnnw','....kn.','....kn.','....n..'],{mirror:false,pal:{n:'#b07a48',d:'#6a4428',k:'#e8e4d4'},shade:false});
  SPR.misc.ice=buildSprite(['...w','..ii','.iiu','iiuu','.iuu','..uu','...u'],{pal:{u:'#4aa3e8'}});
  SPR.misc.crystal=buildSprite(['.....a','....aa','...aac','...aac','..aaac','..aaac','..aabc','...aab','.ddddd','dddddd'],{pal:{a:'#5cd8ff',b:'#2a8ac0',c:'#e0fbff',d:'#4a4a68'}});
}
const eliteSprite=id=>SPR.elite[id]||(SPR.elite[id]=buildSprite(ENEMY_DEFS[id].rows,{pal:ENEMY_DEFS[id].pal,scale:2}));

