    const put=(x,y,w)=>{for(let dx=-w;dx<=w;dx++){const xx=Math.round(x+dx),yy=Math.round(y);if(xx>=0&&yy>=0&&xx<W&&yy<H)m[yy*W+xx]=1;}};
