  init(){fogInit('#c8f0e0');run.fog=[];for(let i=0;i<9;i++)run.fog.push({x:Math.random()*run.map.size,y:Math.random()*run.map.size,v:rnd(4,9),k:i%3,a:rnd(.1,.2)});},
  psp(p){return wetAt(run.built,p.x,p.y)===1?.66:1;},
