// a long wall made of stacked skulls (art painter): w world wide
function makeSkullWall(w,seed){const W=w*Z,H=46;return artSprite(W,H,g=>{const r=mulberry32(seed);
  // stone plinth
  for(let y=H-10;y<H;y+=5)for(let x=-((y/5)&1)*5;x<W;x+=10){const t=['#4a4652','#545060','#423e4a'][(hashN(x,y,seed)*3)|0];g.fillStyle=t;g.fillRect(x,y,10,5);g.fillStyle=mixHex(t,LIGHT_HUE,.18);g.fillRect(x,y,9,1);g.fillStyle='#24202a';g.fillRect(x+9,y,1,5);g.fillRect(x,y+4,10,1);}
  // rows of skulls in mortar, lit from above
  g.fillStyle='#2a241e';g.fillRect(0,6,W,H-16);
  for(let row=0;row<5;row++){const y=H-17-row*6,off=(row&1)*3;for(let x=-off+1;x<W;x+=6){const c=r()<.12?'#bab4a0':r()<.5?'#e4dfcc':'#d2ccb8',sh=row>2?.18:0;
    g.fillStyle=mixHex(c,SHADOW_HUE,sh);g.fillRect(x+1,y,4,4);g.fillRect(x+2,y+4,2,1);g.fillStyle='#1c1814';g.fillRect(x+1,y+2,1,1);g.fillRect(x+3,y+2,1,1);g.fillRect(x+2,y+3,1,1);
    g.fillStyle=mixHex(c,'#ffffff',.35);g.fillRect(x+1,y,2,1);if(r()<.08){g.fillStyle='#e4dfcc';g.fillRect(x,y+5,6,1);}}}
  // a cornice on top and pilasters at both ends
  g.fillStyle='#4e4a58';g.fillRect(0,2,W,5);g.fillStyle='#6e6a78';g.fillRect(0,2,W,1);g.fillStyle='#2e2a36';g.fillRect(0,6,W,1);g.fillStyle='#5a5664';g.fillRect(0,0,W,2);
  for(const x0 of [0,W-6]){g.fillStyle='#55515f';g.fillRect(x0,0,6,H-10);g.fillStyle='#6e6a78';g.fillRect(x0,0,1,H-10);g.fillStyle='#34303c';g.fillRect(x0+5,0,1,H-10);}
  // cobwebs in a corner now and then
  if(r()<.6){const cx=r()<.5?6:W-7,d=cx<10?1:-1;g.fillStyle='rgba(220,220,230,.45)';for(let i=0;i<7;i++){g.fillRect(cx+d*i,7,1,1);g.fillRect(cx,7+i,1,1);g.fillRect(cx+d*Math.round(i*.7),7+Math.round(i*.7),1,1);}}});}
