      if(far>330&&((x+y)&3)===0)return hex2rgb('#c8a040');
      if(edge<2)return hex2rgb('#2a1414');if(edge<3.5)return hex2rgb(((x+y)>>1)&1?'#c8a040':'#8a6a28');if(edge<4.5)return hex2rgb('#5a1a1a');
