  for(let i=0;i<72;i++){const a=i/72*6.283;g.fillStyle=i&1?'#8a6a28':'#c8a040';g.fillRect((C+Math.cos(a)*52)*Z,(C+Math.sin(a)*52)*Z,2,2);}
  const props=[],lights=[],torches=[];const free=(x,y,r)=>!props.some(q=>Math.hypot(q.x-x,q.y-y)<r)&&!torches.some(q=>Math.hypot(q.x-x,q.y-y)<r);
  const swalls={};const sw=w=>swalls[w]||(swalls[w]=makeSkullWall(w,w*7+3));
  for(let gy=1;gy<n;gy++)for(let gx=0;gx<n;gx++){const x0=gx*CELL,y=gy*CELL;if(Math.abs(y-C)<40)continue;if(rng()<.35)continue;
    const L=CELL-34-((rng()*20)|0);for(const part of rng()<.5?[[x0+8,L*.45],[x0+L*.55+22,L*.45]]:[[x0+14,L]]){const [sx,wl]=part;if(Math.abs(sx+wl/2-C)<wl/2+16&&Math.abs(y-C)<60)continue;
      if(sx<20||sx+wl>size-20)continue;const s=sw(Math.round(wl/4)*4);gShadow(g,sx+wl/2,y+1,wl/2,2.5,.45,'#000000');props.push({isProp:true,x:sx+wl/2,y,spr:s,tall:true});}}
