    const x=C+dx*d+(dy?sd*26:0),y=C+dy*d+(dx?sd*26:0);if(!free(x,y,16))continue;const s=crSprite('pillar');gShadow(g,x+2,y,s.w*.45,2.4,.5,'#000000');props.push({isProp:true,x,y,spr:s,tall:true});
