  {const s=crSprite('altar');props.push({isProp:true,x:C,y:C+6,spr:s,tall:false});for(const [dx,dy] of [[-22,-22],[22,-22],[-22,22],[22,22]]){const c=crSprite('candel');props.push({isProp:true,x:C+dx,y:C+dy,spr:c,tall:false});lights.push({x:C+dx,y:C+dy-c.h+2,r:28,col:'#ffcf70',a:1});}}
