  for(let k=0;k<180;k++){const side=(rng()*4)|0,d=22+rng()*110,x=side===0?d:side===1?size-d:40+rng()*(size-80),y=side===2?d:side===3?size-d:40+rng()*(size-80);if(!free(x,y,30))continue;
    const s=pickR(rng,dead);gShadow(g,x+6,y-1,s.w*.4,3.6,.35,'#000000');props.push({isProp:true,x,y,spr:s,tall:true});}
  for(let k=0;k<30;k++){const x=40+rng()*(size-80),y=40+rng()*(size-80);if(Math.hypot(x-C,y-C)<160||!free(x,y,16))continue;const s=crSprite(rng()<.5?'bones':'skulls');props.push({isProp:true,x,y,spr:s,tall:false});}
