  {const r2=mulberry32(def.seed*31+5),n=7,a0=r2()*6.28;
   for(let i=0;i<n;i++)for(let t=0;t<6;t++){const a=a0+i*6.283/n+(r2()-.5)*.5,d=78+r2()*55,x=C+Math.cos(a)*d,y=C+Math.sin(a)*d;
     if(Math.hypot(x-C,y-C-26)<44||!free(x,y,30))continue;add(x,y,pickR(r2,hood),true,1);break;}}
