    for(let c=0;c<2;c++){const x0=c*5;g.fillStyle='#3a1406';for(let j=-3;j<=3;j++)g.fillRect(x0-Math.abs(j)-1,j-.5,3,2);g.fillStyle='#ffe0a0';for(let j=-3;j<=3;j++)g.fillRect(x0-Math.abs(j),j,1.5,1);}
