  for(let k=0;k<70;k++){const x=30+rng()*(size-60),y=30+rng()*(size-60);if(Math.hypot(x-C,y-C)<PR+20||!free(x,y,16))continue;add(x,y,dsSprite(pickR(rng,['cactus','scrub','rock','column','stump','fallen'])),false);}
