    if(ed<TB){const v=(hashN(x>>2,y>>2,3)*.5+hashN(x,y>>1,4)*.3+(ed/TB)*.4+(b-.5)*.2);col=WL[clamp(Math.floor(v*WL.length),0,WL.length-1)];}
