  // the track: gravel bed, sleepers, two steel rails
  const along=(f)=>{for(let i=0;i<rp.length-1;i++){const [x0,y0]=rp[i],[x1,y1]=rp[i+1],L=Math.hypot(x1-x0,y1-y0);f(x0,y0,(x1-x0)/L,(y1-y0)/L,L,i);}};
