function railPos(s){const R=run.built.rails;s=((s%R.len)+R.len)%R.len;let lo=0,hi=R.cum.length-1;while(hi-lo>1){const m=(lo+hi)>>1;if(R.cum[m]<=s)lo=m;else hi=m;}
  const t=(s-R.cum[lo])/((R.cum[hi]-R.cum[lo])||1),a=R.pts[lo],b=R.pts[hi];return{x:a[0]+(b[0]-a[0])*t,y:a[1]+(b[1]-a[1])*t,dx:b[0]-a[0],dy:b[1]-a[1]};}
// runaway mine carts: crush enemies (big score), hurt and shove the player
function updateCarts(dt){
  const R=run.built.rails;if(!R)return;
  if(!run.carts){run.carts=[0,1,2].map(k=>({s:R.len*k/3,x:0,y:0,dir:1}));}
  const p=run.p;
  for(const c of run.carts){c.s+=dt*74;const q=railPos(c.s);c.x=q.x;c.y=q.y;c.dir=q.dx>=0?1:-1;
    if(Math.random()<dt*14&&run.parts.length<400)addP({x:c.x+rnd(-5,5),y:c.y+2,vx:rnd(-30,30),vy:rnd(-50,-15),life:.25,col:pick(['#ffd060','#ff8a30']),sz:1,g:0});
    for(const e of run.enemies){if(e.dead||Math.abs(e.x-c.x)>30||Math.abs(e.y-c.y)>30)continue;const d=Math.hypot(e.x-c.x,e.y-c.y);if(d>11+e.r)continue;
      if(e.want==='smith'){e.kx+=(e.x-c.x)/(d||1)*160;e.ky+=(e.y-c.y)/(d||1)*160;continue;}
      if(e.boss){if((e.cartT||0)>run.t)continue;e.cartT=run.t+.8;hurtEnemy(e,90/Math.max(.2,st.dmg),(e.x-c.x)/d*60,(e.y-c.y)/d*60);}
      else hurtEnemy(e,(e.elite?e.hp*.5:e.hp+10)/Math.max(.2,st.dmg),(e.x-c.x)/(d||1)*120,(e.y-c.y)/(d||1)*120);
      if(e.dead&&run.qc)run.qc.cart++;}
    for(const p of (run.pls?players():[run.p])){if(p.down)continue;const dp=Math.hypot(p.x-c.x,p.y-c.y);
    if(dp<13){if(!run.cartTip){run.cartTip=true;toast(_t('Pozor na vozíky! Drtí i nepřátele'),2600);}
      if(p.inv<=0&&!((run.pls&&p===run.pls[1].p?run.pls[1].st:st).lg||{}).compass){if(run.pls)hurtP(p,hazDm(10,.08,p),'cart');else hurtPlayer(hazDm(10,.08,p),'cart');const n=dp||1;p.x=clamp(p.x+(p.x-c.x)/n*14,14,run.map.size-14);p.y=clamp(p.y+(p.y-c.y)/n*14,14,run.map.size-14);run.shake=6;
        if(run.pls&&p===run.pls[1].p){p.forced=true;p.lock=.35;}}}
    else if(dp<70&&!run.cartTip&&run.t>3){run.cartTip=true;toast(_t('Pozor na vozíky! Drtí i nepřátele'),2600);}}}
}
function rowsCircle(g,x,y,r){for(let dy=-r;dy<=r;dy++){const hw=Math.floor(Math.sqrt(r*r-dy*dy));g.fillRect(x-hw,y+dy,hw*2+1,1);}}

