function weaponDiff(id,lv){ // text for upgrading to level lv (1-based, lv>=2)
  const W=WEAPONS[id],a=W.lv[lv-2],b=W.lv[lv-1],parts=[];
  for(const k in b){if(a[k]===b[k])continue;
    if(k==='cd')parts.push(_t('Rychlejší útok'));
    else if(k==='tick')parts.push(_t('Častější zásahy'));
    else if(W.labels[k]){const d=Math.round((b[k]-a[k])*10)/10;parts.push(W.labels[k]+' '+(d>0?'+':'')+d);}}
  return parts.join(', ')||_t('Silnější');
}

/* ============ meta shop ============ */
// Permanent upgrades: 3 ranks of 10 levels (I gold, II + Bone Dust after the chapter I finale, III + Amber after the chapter II finale).
// Each rank gives half the bonus per level of the one before, prices grow ~13 % a level – a long-term goal. "Second chance" has 3 levels.
const META=[
 {id:'hp',name:_t('Odolnost'),per:5,fmt:v=>'+'+cz(Math.round(v*10)/10)+_t(' zdraví'),base:30,icon:'heart'},
 {id:'dmg',name:_t('Síla'),per:.025,fmt:v=>'+'+cz(Math.round(v*1000)/10)+_t(' % poškození'),base:45,icon:'power'},
 {id:'spd',name:_t('Hbitost'),per:.02,fmt:v=>'+'+cz(Math.round(v*1000)/10)+_t(' % rychlost'),base:35,icon:'boots'},
 {id:'mag',name:_t('Magnetismus'),per:.05,fmt:v=>'+'+cz(Math.round(v*1000)/10)+_t(' % dosah sbírání'),base:25,icon:'magnet'},
 {id:'xp',name:_t('Moudrost'),per:.04,fmt:v=>'+'+cz(Math.round(v*1000)/10)+_t(' % zkušeností'),base:40,icon:'haste'},
 {id:'build',name:_t('Dílna'),per:.025,fmt:v=>'−'+cz(Math.round(v*1000)/10)+_t(' % cena věží'),base:40,icon:'tower'},
 {id:'revive',name:_t('Druhá šance'),rev:1,icon:'potion'}];
const META_RANKS=[{to:10,col:'#d08850'},{to:20,col:'#c8d0dc',mat:'shard',need:'trun'},{to:30,col:'#f6c744',mat:'ess',need:'brana'}],META_MAX=30;
const REV_HP=[0,.5,.7,.9],REV_COST=[{gold:400},{gold:1500,shard:40},{gold:4000,shard:40,ess:10}];
const metaRank=L=>L<10?0:L<20?1:2;
const metaOpen=r=>!META_RANKS[r].need||!!(save.cleared&&save.cleared[META_RANKS[r].need]);
function mB(id,L){const M=META.find(m=>m.id===id);if(!M||!M.per)return 0;L=L||0;return M.per*(Math.min(L,10)+.5*clamp(L-10,0,10)+.25*clamp(L-20,0,10));}
function metaCost(M,L){if(M.rev)return REV_COST[L]||null;if(L>=META_MAX)return null;const c={gold:Math.round(M.base*Math.pow(1.115,L))};
  if(L>=10)c.shard=Math.round((3+(L-10))*2*M.base/35);if(L>=20)c.ess=2+(L-20);return c;}
// old saves had 5 levels (build 4) with the full bonus each: twice the levels keeps the same strength
function metaInit(){if(save.metaV===2)return;const m=save.meta||{};for(const k of ['hp','dmg','spd','mag','xp','build'])m[k]=Math.min(10,(m[k]||0)*2);save.meta=m;save.metaV=2;}

/* ============ audio: music + rhythm ============ */
let ac=null;const sfxT={};
const M={song:null,step:0,acc:0,stepDur:.125,lastAudio:0,int:1,beatPos:0,pulse:0,musicBus:null,sfxBus:null,filter:null,noise:null};
const NOTE=m=>440*Math.pow(2,(m-69)/12);
function audioInit(){
  try{if(!ac){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;ac=new C();
      const master=ac.createGain();master.gain.value=.9;const comp=masterChain(ac,master);
      musicGraph(ac,comp);M.musicBus.gain.value=busVol('m');if(M.song)songMix();
      M.sfxBus=ac.createGain();M.sfxBus.gain.value=busVol('s');
      M.sfxBus.connect(comp);master.connect(ac.destination);M.master=master; // M.master: tests/tools/poslech.js records here
      const len=ac.sampleRate,buf=ac.createBuffer(1,len,ac.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=Math.random()*2-1;M.noise=buf;}
    // iOS leaves the context 'interrupted' (not 'suspended') after the phone was locked, and sometimes reports
    // 'running' while staying silent: resume from any state, and rebuild the context on the next tap if the clock is stuck
    if(M.dead){M.dead=false;try{ac.close();}catch(e){}ac=null;M.lastAudio=0;audioInit();return;}
    if(ac.state!=='running'){const p=ac.resume();if(p&&p.catch)p.catch(()=>{});}
    audioWatch();}catch(e){}
}
let awT=0;
function audioWatch(){if(!ac||document.hidden)return;const t0=ac.currentTime;clearTimeout(awT);
  awT=setTimeout(()=>{if(!ac||document.hidden)return;if(ac.state!=='running'||ac.currentTime===t0)M.dead=true;},800);}
// 09r: volume sliders – the toggle still mutes, the slider (0–1, squared so the whole travel is audible) scales the bus
/* 09z9: music graph – every instrument plays into its own role bus (stereo place + reverb send), then
   musicBus (volume slider) → trim (evens out styles) → energy (calm/run/boss) → duck → muffle → 35 Hz highpass →
   out, plus a "phone bass" path: the lows are saturated into harmonics around 200–600 Hz, which an iPhone speaker can play. */
// 10h: every song is a 'bang' song unless it says bang:false; the denser arrangement is louder, BANG_TRIM brings each style back to the run level (zvuk.js ~-31 dB)
const isBang=S=>!!S&&S.bang!==false;
const BANG_TRIM={grave:-3.6,desert:-3.6,forge:-1.7,frost:-4.4,sea:-2,star:-2.7,title:-.8};
const STYLE_TRIM={desert:1,forge:-3.6,frost:.9,sea:-1.4,star:-1,title:0};
// 09z10: hlasitost nástrojů (dB) podle stylu – změřeno sólo (tests/tools/poslech-offline.js, rolecal): melodie, arpeggio a akordy
// byly o 15–40 dB pod bicími, mix byl z 95 % basy 100–300 Hz → mono, tmavý, z telefonu skoro neslyšný.
// Cíl vůči bicím: basa −3, melodie −4, arpeggio −9, akordy −10. Bicí všude −8 dB kvůli rezervě.
const ROLE_DB={drums:-8,bass:-8,lead:-8,arp:-8,pad:-8,fx:0};
const STYLE_ROLE={grave:{bass:0,lead:19.3,arp:20,pad:9},desert:{bass:4.8,lead:21.9,arp:19.7,pad:10.5},forge:{bass:8,lead:22,arp:22,pad:20.9},
  frost:{bass:1.5,lead:16.4,arp:19.4,pad:16},sea:{bass:6.4,lead:19.4,arp:22,pad:16.7},star:{bass:.3,lead:17.5,arp:22.8,pad:18.7},title:{bass:6.2,lead:20,arp:24,pad:23}};
const MUSIC_LVL=1.9;                        // music level inside the mix
const MASTER_PRE=.55;                       // music + effects into the master; the old soft-knee compressor took ~10 dB, this keeps the overall loudness                 // dB, measured so all chapters sit at the same loudness
const STYLE_REV={grave:.22,desert:.16,forge:.1,frost:.28,sea:.15,star:.3,title:.3}; // reverb return per style
const ENERGY_GAIN=[.82,.92,1,1.3];           // M.int 0 calm intro, 1 run, 2 late run, 3 boss (≈ -1.7 / -0.7 / 0 / +2.3 dB; 10b: boss was only +1–2 dB over the run)
// master: gentle glue compressor (hard knee, so quiet parts keep their dynamics and the boss is really louder) + a safety limiter.
// The old one had the default 30 dB soft knee and squashed everything above ~-29 dB, which flattened calm vs boss.
function masterChain(c,out,old){const comp=c.createDynamicsCompressor();
  if(old){comp.threshold.value=-14;comp.ratio.value=4;comp.connect(out);return comp;}
  comp.threshold.value=-16;comp.knee.value=6;comp.ratio.value=2.5;comp.attack.value=.006;comp.release.value=.2;
  const lim=c.createDynamicsCompressor();lim.threshold.value=-3;lim.knee.value=0;lim.ratio.value=20;lim.attack.value=.001;lim.release.value=.12;
  comp.connect(lim);lim.connect(out);const pre=c.createGain();pre.gain.value=MASTER_PRE;pre.connect(comp);return pre;}
function musicGraph(c,out){const G=()=>c.createGain(),F=(type,f,q)=>{const n=c.createBiquadFilter();n.type=type;n.frequency.value=f;if(q!=null)n.Q.value=q;return n;};
  const bus=G(),trim=G(),energy=G(),duck=G(),filter=F('lowpass',18000),hp=F('highpass',35,.7),ls=F('lowshelf',110),pres=F('peaking',2500,.8),lvl=G();ls.gain.value=-3;pres.gain.value=3;lvl.gain.value=MUSIC_LVL;
  bus.connect(trim);trim.connect(energy);energy.connect(duck);duck.connect(filter);filter.connect(hp);hp.connect(ls);ls.connect(pres);pres.connect(lvl);lvl.connect(out);
  // phone bass: low band → soft clip → keep only the new harmonics
  const lo=F('lowpass',190,.7),sh=c.createWaveShaper(),hh=F('highpass',400,.7),hg=G();const cv=new Float32Array(1024);
  for(let i=0;i<1024;i++){const x=i/511.5-1;cv[i]=Math.tanh(x*4)/Math.tanh(4);}sh.curve=cv;hg.gain.value=.8;
  filter.connect(lo);lo.connect(sh);sh.connect(hh);hh.connect(hg);hg.connect(lvl);
  // reverb: generated stereo room (no files), fed by the role sends, returns into the music bus so volume and ducking apply
  const rev=c.createConvolver(),rr=G();
  // 10d: impulse built cheaply (decay by multiplication, 1.4 s) and, live, one frame later – on a slow phone the old loop stalled the first tap ~150 ms
  const mkIR=()=>{const sr=c.sampleRate,len=Math.floor(sr*1.4),ir=c.createBuffer(2,len,sr),pre=Math.floor(sr*.012),k=Math.exp(-2.6/sr);
    for(let ch=0;ch<2;ch++){const d=ir.getChannelData(ch);let e=1;for(let i=pre;i<len;i++){e*=k;const f=1-i/len;d[i]=(Math.random()*2-1)*e*f*f;}}rev.buffer=ir;};
  if(c instanceof OfflineAudioContext)mkIR();else setTimeout(mkIR,60);const rlp=F('lowpass',4200);rev.connect(rlp);rlp.connect(rr);rr.connect(bus);rr.gain.value=.2;
  const pan=v=>{if(c.createStereoPanner){const n=c.createStereoPanner();n.pan.value=v;return n;}return G();};
  const pump=G();pump.connect(bus);const role=(p,send,dst)=>{const g=G(),pn=pan(p);g.connect(pn);pn.connect(dst||bus);if(send){const s=G();s.gain.value=send;g.connect(s);s.connect(rev);}return g;};
  const R={drums:role(0,.08),bass:role(0,0,pump),arp:role(-.32,.35),lead:role(.1,.3),fx:role(.22,.2)};
  // pad: Haas widening (one side 14 ms later) so chords spread around the player
  {const g=G(),pl=pan(-.7),pr=pan(.7),dl=c.createDelay(.05);dl.delayTime.value=.014;g.connect(pl);pl.connect(pump);g.connect(dl);dl.connect(pr);pr.connect(pump);const s=G();s.gain.value=.5;g.connect(s);s.connect(rev);R.pad=g;}
  M.musicBus=bus;M.trim=trim;M.energy=energy;M.duck=duck;M.filter=filter;M.revRet=rr;M.roles=R;M.pump=pump;return R;}
function busVol(k){const v=save.vol?save.vol[k]:1,on=k==='m'?save.music:save.sound,base=k==='m'?.3:.5;return on?base*Math.pow(v==null?1:v,2):0;}
function setBuses(){if(!M.musicBus)return;M.musicBus.gain.setTargetAtTime(busVol('m'),ac.currentTime,.05);M.sfxBus.gain.setTargetAtTime(busVol('s'),ac.currentTime,.05);}
// music ducks under the big moments (boss, death, ultimate drops) so they punch through, then comes back
function duckMusic(db,hold){if(!M.duck||!ac)return;const g=M.duck.gain,t=ac.currentTime;try{g.cancelScheduledValues(t);g.setValueAtTime(g.value,t);g.setTargetAtTime(Math.pow(10,(db||-9)/20),t,.02);g.setTargetAtTime(1,t+(hold||.35),(hold||.35)>1?.4:.22);}catch(_){}}
function muffle(on){if(!M.filter)return;try{M.filter.frequency.setTargetAtTime(on?650:18000,ac.currentTime,.08);}catch(e){}}
function env(g,t,a,d,v){g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,v),t+a);g.gain.exponentialRampToValueAtTime(.0001,t+a+d);}
function osc(type,f,t,dur,vol,bus,slide,lp){const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(f,t);
  if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(20,slide),t+dur);
  if(lp){const fl=ac.createBiquadFilter();fl.type='lowpass';fl.frequency.value=lp;o.connect(fl);fl.connect(g);}else o.connect(g);
  g.connect(bus);env(g,t,.003,dur,vol);o.start(t);o.stop(t+dur+.05);}
function noiz(t,dur,vol,bus,type,freq){const n=ac.createBufferSource(),f=ac.createBiquadFilter(),g=ac.createGain();n.buffer=M.noise;f.type=type||'bandpass';f.frequency.value=freq||2000;
  n.connect(f);f.connect(g);g.connect(bus);env(g,t,.002,dur,vol);n.start(t,Math.random()*.5);n.stop(t+dur+.05);}
function setSong(id){M.song=SONGS[id]||(CH_OF[id]&&SONGS[CH_OF[id].maps[0]])||SONGS.menu;songMix();M.stepDur=60/M.song.bpm/4;M.step=0;M.acc=0;M.int=id==='menu'?2:0;M.bossBar=null;M.lastLead=null;}
function songMix(){if(!ac||!M.trim)return;const st=M.song.style,t=ac.currentTime,SR=STYLE_ROLE[st]||{};try{
  if(M.roles)for(const k in M.roles){const g=M.roles[k].gain;if(g.value===0&&M.offline)continue;g.setTargetAtTime(Math.pow(10,((ROLE_DB[k]||0)+(SR[k]||0))/20),t,.05);}M.trim.gain.setTargetAtTime(Math.pow(10,((STYLE_TRIM[st]||0)+(isBang(M.song)?BANG_TRIM[st]||0:0))/20),t,.05);M.revRet.gain.setTargetAtTime(STYLE_REV[st]!=null?STYLE_REV[st]:.2,t,.05);}catch(_){}}
