  if(o.vib&&dur>.18){const l=ac.createOscillator(),lg=ac.createGain();l.frequency.value=o.vib;lg.gain.setValueAtTime(0,t);lg.gain.linearRampToValueAtTime(f*.014,t+Math.min(.25,dur*.5));l.connect(lg);lg.connect(os.frequency);l.start(t);l.stop(t+dur+.06);}
