 clap(t,v){const B=M.musicBus;noiz(t,.02,.14*v,B,'bandpass',1300);noiz(t+.011,.02,.12*v,B,'bandpass',1250);noiz(t+.022,.16,.2*v,B,'bandpass',1200);},
