function bossIntroStart(e){const id=e.id,fin=!!run.map.finale,T=biTheme(id),sp=SPR.boss[id];
  const nm=BOSS_DEFS[id].name,cm=nm.indexOf(','),main=(cm>0?nm.slice(0,cm):nm.split(' ').length>2&&nm.length>12?nm.split(' ')[0]:nm).toUpperCase(),sub=cm>0?nm.slice(cm+1).trim():main.length<nm.length?nm.slice(main.length).trim():'';
  let size=fin?30:26;const m=document.createElement('canvas').getContext('2d');m.font='700 '+size+'px '+getComputedStyle(document.documentElement).getPropertyValue('--font-px');
  while(size>14&&m.measureText(main).width>VW*.78){size--;m.font='700 '+size+'px '+getComputedStyle(document.documentElement).getPropertyValue('--font-px');}
  const gold=['#fff6c8','#ffe27a','#f6c744','#d89a2a','#a8641e'];
  const beat=M.stepDur*4,ln=(T.line||'').length,beats=Math.max(fin?9:7,Math.ceil((2.5*beat+ln/BI_TYPE+(fin?3.2:2.6))/beat+.6)); // 10b: was 5/7 beats (~2.7 s), the line was readable ~0.6 s
  BI={id,e,fin,t:0,beat,beats,T,card:biCard(T,fin,VW,VH),sp,sil:biTint(sp,'#000000'),glow:biTint(sp,fin?'#ff5a3a':T.acc),
    title:biText(main,size,gold,-.16),sub:sub?biText(sub.toUpperCase(),Math.max(10,Math.round(size*.42)),['#ffffff','#e8e4dc','#bfb8c8'],-.16):null,
    line:T.line,ribbon:fin?biText(_t('FINÁLE KAPITOLY'),11,['#ffffff','#ffd0c0'],0):null,typed:0};
  $('#hud').classList.add('bi');$('#toast').classList.remove('on');bossIntroSfx(fin);}
// draws on top of everything; k = time in beats
function drawBossIntro(g){const B=BI;if(!B)return;const k=B.t/B.beat,N=B.beats,out=clamp((k-(N-.6))/.6,0,1),ease=x=>1-Math.pow(1-x,3),gone=Math.round(ease(out)*VW*1.3);
  g.save();g.globalAlpha=clamp(k*3,0,1)*.7*(1-out);g.fillStyle='#000000';g.fillRect(0,0,VW,VH);g.globalAlpha=1;
  const sc0=Math.max(2,Math.floor(Math.min(VW*(B.fin?.7:.58)/B.sp.w,VH*(B.fin?.42:.34)/B.sp.h)));
  // probliknutí: two white flashes on the first two eighths, the boss as a black silhouette in a burst
  if(k<1){const fl=(k<.12||(k>.25&&k<.37));if(fl){g.fillStyle='#ffffff';g.fillRect(0,0,VW,VH);}
    else{g.globalAlpha=.9;g.fillStyle=B.fin?'#c8402a':B.T.acc;for(let i=0;i<14;i++){const a=i/14*6.283+k;g.beginPath();g.moveTo(VW/2,VH*.45);g.lineTo(VW/2+Math.cos(a)*VW,VH*.45+Math.sin(a)*VW);g.lineTo(VW/2+Math.cos(a+.18)*VW,VH*.45+Math.sin(a+.18)*VW);g.closePath();g.fill();}g.globalAlpha=1;}
    g.drawImage(B.sil,RZ(VW/2-B.sp.w*sc0/2),RZ(VH*.45-B.sp.h*sc0/2),B.sp.w*sc0,B.sp.h*sc0);}
  else{const k1=k-1,slide=ease(clamp(k1/.6,0,1)),ox=Math.round((1-slide)*VW)-gone,sh=k1<.25||(B.fin&&k1>1&&k1<1.2)?Math.round((Math.random()-.5)*(B.fin?6:3)):0;
    g.drawImage(B.card,ox+sh,sh);
    if(B.ribbon&&k1>.6){const ry=Math.round(VH*.16),rw=B.ribbon.width,rx=6-gone;g.fillStyle='#140c1c';g.fillRect(0,ry-2,VW,17);g.fillStyle='#8a1a1a';g.fillRect(0,ry,VW,13);
      for(let x=(B.t*30|0)%12-12;x<VW;x+=12){g.fillStyle='#b8301e';g.fillRect(x,ry,6,13);}g.drawImage(B.ribbon,rx,Math.round(ry+6-B.ribbon.height/2));}
    // the boss, big, breaking out over the band's upper edge; finale: a pulsing glow outline
    const sc=sc0,bw=B.sp.w*sc,bh=B.sp.h*sc,cx=VW*.68,top=VH*.27-cx*.16,bx=RZ(cx-bw/2)+Math.round((1-ease(clamp(k1/.8,0,1)))*VW*.6)-gone+sh,by=RZ(top-bh*.32)+Math.round(Math.sin(B.t*3)*1.5)+sh;
    if(B.fin){g.globalAlpha=.55+.35*Math.sin(B.t*10);for(const [dx,dy] of [[-1,0],[1,0],[0,-1],[0,1],[-2,0],[2,0],[0,-2]])g.drawImage(B.glow,bx+dx,by+dy,bw,bh);g.globalAlpha=1;}
    g.globalAlpha=.35;g.fillStyle='#000000';g.fillRect(bx+Math.round(bw*.15),by+bh-2,Math.round(bw*.7),3);g.globalAlpha=1;
    const rev=clamp((k1-.35)/.3,0,1);g.drawImage(B.sp.c,bx,by,bw,bh);if(rev<1){g.globalAlpha=1-rev;g.drawImage(B.sil,bx,by,bw,bh);g.globalAlpha=1;}
    if(k1>.35&&k1<.5){g.globalAlpha=.7*(1-(k1-.35)/.15);g.fillStyle='#ffffff';g.fillRect(0,0,VW,VH);g.globalAlpha=1;}
    // title slams in with an overshoot (second beat), the sub-title under it, then the one-liner types out
    const tk=k1-1;if(tk>0){const s2=tk<.25?2.2-1.3*ease(tk/.25):tk<.4?.9+.1*ease((tk-.25)/.15):1,tw=B.title.width,th=B.title.height,tx=Math.round(clamp(VW*.4,tw/2+4,VW-tw/2-4))-gone,ty=Math.round(VH*.52);
      g.drawImage(B.title,Math.round(tx-tw*s2/2),Math.round(ty-th*s2/2),Math.round(tw*s2),Math.round(th*s2));
      if(B.sub&&tk>.3)g.drawImage(B.sub,Math.round(tx-B.sub.width/2+th*.12),Math.round(ty+th*.46));
}}
  g.restore();biLineSet(B,gone);}
function bossIntroTick(dt){if(!BI)return false;BI.t+=dt;if(BI.t>=BI.beat*BI.beats){bossIntroEnd();return false;}return true;}
function bossIntroEnd(){if(!BI)return;BI=null;biLineHide();$('#hud').classList.remove('bi');if(run){run.shake=6;run.flashScr=Math.max(run.flashScr||0,.15);}}
// a tap skips to the slide-out
function bossIntroSkip(){if(BI){const out=BI.beat*(BI.beats-.6);if(BI.t<out)BI.t=out;}}
// sound: two clicks for the flashes, a whoosh for the card, a slam with a metal clang on the beat; finale adds a low choir and thunder
function bossIntroSfx(fin){if(!save.sound||!ac||!M.sfxBus||!M.song||(ac.state!=='running'&&!M.offline))return;const B=M.sfxBus,sd=M.stepDur,t=Math.max(ac.currentTime+.01,M.lastAudio||ac.currentTime),c=chordAt(Math.max(0,M.step-1));
  try{noiz(t,.04,.3,B,'highpass',5000);noiz(t+sd*2,.04,.3,B,'highpass',5000);osc('square',NOTE(c.root+36),t,.05,.04,B);osc('square',NOTE(c.root+36),t+sd*2,.05,.04,B);
    noizSweep(t+sd*3,sd*2,.18,'bandpass',300,5000,2,sd*1.6);duckBeat(t+sd*4,.15,.5);
    const u=t+sd*4;osc('sine',190,u,.7,.65,B,32);noiz(u,.4,.3,B,'lowpass',900);noizSweep(u,1.6,.14,'highpass',7000,3500);
    for(const n of c.tones){const f=NOTE(c.root+12+n);osc('square',f,u,.5,.04,B,null,2200);osc('sine',f*2.76,u,.9,.025,B);}
    const v=t+sd*8;osc('sine',150,v,.4,.4,B,40);noiz(v,.12,.2,B,'bandpass',1800);
    for(let i=0;i<8;i++)osc('square',NOTE(c.root+24+c.tones[i%3]),t+sd*(10+i),.03,.02,B,null,3000);
    if(fin){const w=t+sd*12;osc('sine',120,w,1.2,.55,B,28);noizSweep(w,2.2,.26,'lowpass',800,70,0,.05);
      for(const n of c.tones)for(const dt of [-9,9]){tone('sawtooth',NOTE(c.root+n),u,sd*16,.02,{lp:1200,a:.25,det:dt,bus:B});}
      noizSweep(t+sd*4,.2,.3,'highpass',8000,2500);}}catch(e){}}
// ----- Endless Crypt (08l): the map's boss again and again, each time stronger and with a new attack -----
const EVO_TXT=[null,null,_t('Nově: kruhy střepů.'),_t('Nově: volá elitní pomocníky.'),_t('Nově: zuří a je rychlejší.'),_t('Nově: vějíře střel.'),_t('Nově: nechává za sebou žhavé louže.'),_t('Teď útočí ještě častěji.')];
function bossEvo(e,tp){if(!run.barNow)return;e.bc=(e.bc||0)+1;const n=e.bc,fast=e.evo>=7,src=srcOf(e);
  if(e.evo>=2&&(fast||n%2===0)){ring(e.x,e.y,12,52,e.dmg*.45,n*.37,src);sfx('zap');}
  if(e.evo>=3&&n%4===2){for(let i=0;i<2;i++){const a=Math.random()*6.283,q=makeEnemy(chooseEnemy(),clamp(e.x+Math.cos(a)*30,16,run.map.size-16),clamp(e.y+Math.sin(a)*30,16,run.map.size-16),true);run.enemies.push(q);}}
  if(e.evo>=5&&(fast||n%2===1)&&tp)fan(e.x,e.y,Math.atan2(tp.y-e.y,tp.x-e.x),7,.2,66,e.dmg*.4,src);
  if(e.evo>=6&&tp&&n%3===0)run.fx.push({k:'magma',x:tp.x+rnd(-20,20),y:tp.y+rnd(-20,20),r:12,life:4,max:4,seed:Math.random()*9});}
function enBossDown(e){run.enW=(run.enW||0)+1;run.bossSpawned=false;run.enNext=run.t+12;run.coins+=20+10*run.enW;
  for(const q of players())if(!q.down)q.hp=Math.min(q.max,q.hp+Math.ceil(q.max*.25));
  toast(_t('Boss poražen! Za chvíli se vrátí silnější…'),2600);sfx('win');}
function ring(x,y,n,spd,dmg,off,src){for(let i=0;i<n;i++){const a=(i/n)*6.283+(off||0);run.eshots.push({x,y,vx:Math.cos(a)*spd,vy:Math.sin(a)*spd,dmg,r:3,life:5,src});}}

function updateEnemies(dt){
  const p=run.p,t=run.t,cr=run.crystal;let crDps=0;
  for(const e of run.enemies){
    if(e.dead)continue;
    e.flash=Math.max(0,e.flash-dt);e.slowT=Math.max(0,e.slowT-dt);if(e.frz>0)e.frz-=dt;
    // target: the player when close (or always for bosses), otherwise the crystal if the map has one
    const tp=run.pls?nearPl(e.x,e.y):p,pdx=tp.x-e.x,pdy=tp.y-e.y,pd=Math.hypot(pdx,pdy)||1;
    let dx=pdx,dy=pdy,dist=pd;
    if(cr&&!e.boss&&!(run.map.caravan&&e.par)){if(e.tp){if(pd>95)e.tp=false;}else if(pd<70)e.tp=true;
      if(!e.tp){dx=cr.x-e.x;dy=cr.y-e.y;dist=Math.hypot(dx,dy)||1;}}
    const ux=dx/dist,uy=dy/dist;
    let sp=e.spd*(e.pin>run.t?0:e.frz>0?.1:e.slowT>0?.55:1)*(mfCall('espd',e)||1),vx=0,vy=0;const beh=e.boss?e.d.pat:e.d.beh;
    if(e.boss)sp*=bossRage(e);
    let tx=dx,ty=dy;if(!e.boss&&dist>34){tx=dx+e.off.x;ty=dy+e.off.y;}const tl=Math.hypot(tx,ty)||1;const cx=tx/tl,cy=ty/tl;
    switch(beh){
      case'wave':{const w=Math.sin(t*4+e.phase);vx=(cx+(-cy)*w*.9)*sp;vy=(cy+cx*w*.9)*sp;break;}
      case'ghost':{const w=Math.sin(t*1.5+e.phase)*.5;vx=(cx-cy*w)*sp;vy=(cy+cx*w)*sp;break;}
      case'ranged':{const want=dist>88?1:dist<60?-.8:0;vx=cx*sp*want;vy=cy*sp*want;
        e.shootT-=dt;if(e.shootT<=0&&dist<150&&run.beatNow){e.shootT=2.3;run.eshots.push({x:e.x,y:e.y,vx:ux*55,vy:uy*55,dmg:8*(1+t/60*.08),r:3,life:4,src:srcOf(e)});}break;}
      case'charger':case'dashring':{
        if(e.mode===0){vx=cx*sp*.75;vy=cy*sp*.75;e.mT-=dt;if(e.mT<=0&&dist<(e.boss?170:100)&&run.beatNow){e.mode=1;e.mT=M.stepDur*4*(e.boss?2:1);e.dx=ux;e.dy=uy;}}
        else if(e.mode===1){e.mT-=dt;e.dx=ux;e.dy=uy;if(e.mT<=0){e.mode=2;e.mT=M.stepDur*4*(e.boss?1.5:1);}}
        else{vx=e.dx*sp*(e.boss?3.4:4);vy=e.dy*sp*(e.boss?3.4:4);e.mT-=dt;if(e.mT<=0){e.mode=0;e.mT=e.boss?rnd(5,6.5):rnd(2,3.2);}}
        if(beh==='dashring'){e.tA-=dt;if(e.tA<=0&&run.beatNow){e.tA=3.2;ring(e.x,e.y,12,52,e.dmg*.55,Math.random()*6,srcOf(e));sfx('boom');}}
        break;}
      case'summon':{vx=cx*sp;vy=cy*sp;e.tA-=dt;
        if(e.tA<=0&&run.barNow){e.tA=4.5;for(let i=0;i<3;i++){const a=Math.random()*6.283,s=makeEnemy('slime',e.x+Math.cos(a)*26,e.y+Math.sin(a)*26,false);run.enemies.push(s);}toast(_t('Sliz se dělí!'),1200);}
        break;}
      case'ring':{const want=dist>100?1:dist<70?-.8:0;vx=cx*sp*want;vy=cy*sp*want;
        e.tA-=dt;if(e.tA<=0&&run.beatNow){e.tA=2.2;ring(e.x,e.y,10,48,e.dmg*.6,t*1.7,srcOf(e));sfx('zap');}
        e.tB-=dt;if(e.tB<=0&&run.barNow){e.tB=7;for(let i=0;i<3;i++){const a=Math.random()*6.283;run.enemies.push(makeEnemy('skeleton',e.x+Math.cos(a)*22,e.y+Math.sin(a)*22,false));}}
        break;}
      default:{const r=BEH[beh];if(r){const v=r(e,dt,{cx,cy,ux,uy,dist,sp,t,tp});vx=v[0];vy=v[1];}else{vx=cx*sp;vy=cy*sp;}}
    }
    if(e.evo>1)bossEvo(e,tp);
    if(e.boss&&e.rage)rageHunt(e,tp,pd,dt);
    e.x+=(vx+e.kx)*dt;e.y+=(vy+e.ky)*dt;
    const kd=Math.max(0,1-9*dt);e.kx*=kd;e.ky*=kd;
    const sz=run.map.size;e.x=clamp(e.x,14,sz-14);e.y=clamp(e.y,14,sz-14);
    if(pd<e.r+tp.r&&!e.bur&&!e.d.noHit){if(run.pls)hurtP(tp,e.dmg,srcOf(e));else hurtPlayer(e.dmg,srcOf(e));if(e.d.touch==='poison')tp.psn=Math.max(tp.psn||0,1.8);else if(e.d.touch==='slow')tp.slw=Math.max(tp.slw||0,.9);}
    if(cr&&Math.hypot(e.x-cr.x,e.y-cr.y)<e.r+cr.r+2)crDps+=e.dmg*(e.boss?.8:.15);
  }
  if(cr&&crDps>0&&!(window.__krypta&&window.__krypta.god)){cr.hp-=Math.min(crDps,30)*dt;cr.flash=.12;cr.hit=true;}
}
// a boss that is not beaten in BOSS_RAGE s starts to rage: faster and harder-hitting every minute (no endless kiting/farming)
const BOSS_RAGE=120;
function bossRage(e){const over=run.t-(e.born===undefined?run.t:e.born)-BOSS_RAGE;if(over<=0)return 1;
  if(!e.rage){e.rage=1;e.dmg0=e.dmg;toast(e.d.name+_t(' zuří!'),2400);sfx('boss');run.shake=5;$('#bossbar').classList.add('rage');}
  const k=over/60;e.dmg=e.dmg0*(1+.6*k);return Math.min(3.2,1.3+.3*k);}
// a raging boss also lunges at a player who keeps running away: telegraph (1 beat), then a dash; more often and further every minute, so kiting ends
function rageHunt(e,tp,pd,dt){if(!e.rage||run.endless||!e.d)return;const k=Math.max(0,(run.t-e.born-BOSS_RAGE)/60);
  if(e.rhD>0){e.rhD-=dt;e.x+=e.rhx*dt;e.y+=e.rhy*dt;if(Math.random()<.7)sparks(e.x,e.y,1,'#ff5a3a',-e.rhx,-e.rhy,60);return;}
  if(e.rhW>0){e.rhW-=dt;if(e.rhW<=0&&e.d.pat==='kraken'){fan(e.x,e.y,Math.atan2(tp.y-e.y,tp.x-e.x),5+2*Math.min(4,Math.floor(k)),.14,84,e.dmg*.4,srcOf(e));sfx('boom');return;}if(e.rhW<=0){const a=Math.atan2(tp.y-e.y,tp.x-e.x),L=Math.max(0,Math.min(pd-12,90+45*k)),T=.3;e.rhx=Math.cos(a)*L/T;e.rhy=Math.sin(a)*L/T;e.rhD=T;sfx('boom');run.shake=Math.max(run.shake||0,4);
      if(k>=1.5)ring(e.x,e.y,10+Math.min(8,Math.floor(k)*2),54,e.dmg*.4,Math.random()*6,srcOf(e));}return;}
  e.rhT=(e.rhT===undefined?2:e.rhT)-dt;
  if(e.rhT<=0&&pd>64&&run.beatNow){e.rhT=Math.max(2,5.5-1.1*k);e.rhW=M.stepDur*4;run.fx.push({k:'shock',x:e.x,y:e.y,r:4,t:0,life:.5,col:'#ff4a3a'});}}
/* ----- juicy effects: particle helper, sprite shatter, sparks, smoke ----- */
const P_MAX=520;
function addP(q){if(run.parts.length<pCap())run.parts.push(q);}
// break a sprite canvas into tumbling chunks that bounce on the ground
function shatter(img,cx,top,gy,n,pow){const W=img.width,H=img.height,cw=Math.ceil(W/n),chh=Math.ceil(H/n);pow=pow||1;
  for(let j=0;j<n;j++)for(let i=0;i<n;i++){if(run.parts.length>=pCap())return;const sx=i*cw,sy=j*chh,dx=(i+.5)/n-.5,dy=(j+.5)/n-.5;
    run.parts.push({k:'chunk',img,sx,sy,sw:cw,sh:chh,x:cx+dx*W/Z,y:top+(j+.5)*H/Z/n,vx:(dx*140+rnd(-25,25))*pow,vy:(rnd(-110,-50)+dy*40)*pow,life:rnd(.55,.85),rot:0,vr:rnd(-14,14),gy:gy+rnd(-2,2)});}}
function sparks(x,y,n,col,dirx,diry,spd){for(let i=0;i<n;i++){let a=Math.random()*6.283;if(dirx||diry)a=Math.atan2(diry,dirx)+rnd(-.7,.7);const v=rnd(.6,1)*(spd||110);
  addP({k:'streak',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rnd(.1,.18),col:col||'#ffffff',g:0,drag:6});}}
function smokePuff(x,y,n,col,size){for(let i=0;i<n;i++)addP({k:'smoke',x:x+rnd(-4,4),y:y+rnd(-4,4),vx:rnd(-22,22),vy:rnd(-30,-8),life:rnd(.5,.95),max:.95,sz:rnd(1.5,2.5)*(size||1),grow:5*(size||1),drag:2.5,g:0,col:col||'#5a5068',a:.5});}
function hurtEnemy(e,dmg,kx,ky){
  if(e.dead||e.bur||isGuest())return;
  if(e.shield){e.flash=.05;if(Math.random()<.3)sparks(e.x,e.y-4,2,'#b07aff',kx,ky,90);if(!e.shT||run.t-e.shT>2.5){e.shT=run.t;toast(e.shield,1600);}return;}
  let d=dmg*st.dmg*(mfCall('dmgMul',e)||1)*(st.af&&st.af.hunter&&(e.boss||e.elite)?1+st.af.hunter:1),crit=false;if(e.mk>run.t)d*=e.mkm||1.2;if(e.elite&&run.thm==='hunt')d*=1.2;if(st.lg&&st.lg.skyW&&(e.boss||e.elite))d*=1.15;if(st.tr&&st.tr.a5)d*=1+Math.min(.025*st.tr.a5,run.combo/1000);if(Math.random()<(st.crit||.1)+(st.tr&&st.tr.a1&&(M.step%16)<4?.03*st.tr.a1:0)+(st.af&&st.af.rhythm&&(M.step%16)<4?st.af.rhythm:0)){d*=st.tal&&st.tal.a20?2:1.6;crit=true;}if(st.lg&&st.lg.metro&&(M.step%16)>=12)d*=2;d=Math.max(1,Math.round(d));
  if(crit&&st.lg&&st.lg.storm&&run.t-(run.sgT||-9)>.5){run.sgT=run.t;explode(e.x,e.y,26,10+run.level*1.5);}
  run.tdm=(run.tdm||0)+d;e.hp-=d;if(st.lg&&st.lg.sfr2&&!e.boss)e.slowT=Math.max(e.slowT,.8);e.flash=.09;e.sq=1;e.kx+=(kx||0)*e.kbm;e.ky+=(ky||0)*e.kbm;
  if(run.nums.length<40)run.nums.push({x:e.x+rnd(-3,3),y:e.y-e.h/2,vx:rnd(-14,14),vy:crit?-70:-55,txt:String(d)+(crit?'!':''),life:crit?.8:.6,col:crit?'#f6c744':'#ffffff',big:crit,t:0});
  sparks(e.x,e.y-2,crit?5:2,crit?'#fff6b0':'#ffffff',kx,ky,crit?150:110);
  if(crit)run.fx.push({k:'pop',x:e.x,y:e.y-2,r:2,max:9,life:.12,t:0,col:'#f6c744'});
  sfx('hit');if(e.hp<=0)killEnemy(e);
}
function killEnemy(e){
  e.dead=true;if(run.pls){(CO.kills||(CO.kills=[])).push(e.nid||0);}run.kills++;
  if(st&&st.af&&!e.d.noHit){if(st.af.vamp&&!run.p.down)run.p.hp=Math.min(run.p.max,run.p.hp+st.af.vamp);if(st.af.gold&&e.elite)run.coins+=Math.round(st.af.gold);}run.combo++;run.comboT=(st&&st.tal&&st.tal.d5?2.4:1.6)+(run.thm==='rhythm'?1:0);sfx('kill');
  const Q=run.qc;if(Q){Q.k[e.id]=(Q.k[e.id]||0)+1;if(e.elite)Q.el++;if(e.boss)Q.boss++;if(run.combo>Q.combo)Q.combo=run.combo;
    if(e.want){Q.want=e.want;run.wanted=null;toast(_t('Hledaný dopaden! Odměnu si vyzvedni na Nástěnce'),2800);run.items.push({x:e.x-6,y:e.y,k:'mat',v:8});for(let i=0;i<3;i++)run.items.push({x:e.x+rnd(-8,8),y:e.y+rnd(-8,8),k:'coin'});}}
  // combo milestones pay more the longer the combo lasts: 25 → 5, 50 → 10 … up to 40 gold (spent in the run on towers; only
  // part of the run's gold is kept afterwards, see endCoins); every 200 also drops material
  if(run.combo%25===0){const g=Math.min(40,5*(run.combo/25));run.coins+=g;const big=run.combo%200===0;
    if(big&&MAT_OF[run.mapId])run.items.push({x:run.p.x+rnd(-14,14),y:run.p.y+rnd(-14,14),k:'mat',v:2+Math.min(3,Math.floor(run.combo/300))});
    toast(_t('Kombo ')+run.combo+'! +'+g+_t(' zlata')+(big&&MAT_OF[run.mapId]?_t(' a Úlomky'):''),big?1600:1000);sfx(big?'level':'coin');
    if(st&&st.tal&&st.tal.d20){const p=run.p;run.fx.push({k:'ring',x:p.x,y:p.y,r:2,max:110,dmg:20+run.level*2,hit:new Set(),life:1,noslow:true,col:'#7fe0c8'});}}
  const pal=e.d.pal||{},pa=pal.a||'#c869e0',cols=[pa,pal.b||mixHex(pa,SHADOW_HUE,.4),pal.c||mixHex(pa,LIGHT_HUE,.4),mixHex(pa,'#120c1a',.6)];
  const gy=e.y+e.h/2-4,n=e.boss?30:e.elite?12:5;
  for(let i=0;i<n;i++)addP({x:e.x+rnd(-3,3),y:e.y+rnd(-3,3),vx:rnd(-55,55),vy:rnd(-95,-25),life:rnd(.5,.85),col:pick(cols),sz:e.boss?3:(Math.random()<.35?1:2),gy});
  if(e.spr&&!e.bur){const img=e.flash>0?e.spr.c:e.spr.c;shatter(img,e.x,e.y-e.spr.h/2,gy,e.boss?5:e.elite?4:3,e.boss?1.4:1);}
  addP({k:'smoke',x:e.x,y:e.y-2,vx:0,vy:-18,life:.6,max:.6,sz:2,grow:6,drag:1,g:0,col:'#ffffff',a:.35});
  sparks(e.x,e.y-2,e.boss?14:e.elite?8:4,mixHex(pa,'#ffffff',.5),0,0,130);
  run.fx.push({k:'pop',x:e.x,y:e.y,r:2,max:e.r*2+7,life:.18,t:0});
  if(e.elite||e.boss)run.hitstop=Math.max(run.hitstop||0,e.boss?.25:.08);
  const v=e.xp;
  if(run.gems.length>220){const g=pick(run.gems);g.v+=v;}else run.gems.push({x:e.x,y:e.y,v});
  if(e.elite||e.boss)run.items.push({x:e.x,y:e.y,k:'chest'});
  if(MAT_OF[run.mapId]){if(e.boss){}else if(e.elite)run.items.push({x:e.x+6,y:e.y,k:'mat',v:rndi(2,3)+Math.round(.3*((st&&st.tr&&st.tr.l4)||0))});else if(Math.random()<.01)run.items.push({x:e.x,y:e.y,k:'mat',v:1});}
  else{const r=Math.random();
    if(r<.10)run.items.push({x:e.x,y:e.y,k:'coin'});
    else if(r<.106)run.items.push({x:e.x,y:e.y,k:'heart'});
    else if(r<.11)run.items.push({x:e.x,y:e.y,k:'magnet'});}
  if(e.d.die==='puddle')run.fx.push({k:'puddle',x:e.x,y:e.y+2,r:11,life:5,max:5,seed:Math.random()*9});
  else if(e.d.die==='magma')run.fx.push({k:'magma',x:e.x,y:e.y+2,r:9,life:3,max:3,seed:Math.random()*9});
  else if(e.d.die==='snow'){if(!isGuest())ring(e.x,e.y-3,e.elite?6:4,42,4*(1+run.t/60*.08),Math.random()*6,srcOf(e));for(let i=0;i<8;i++)addP({x:e.x+rnd(-4,4),y:e.y-4,vx:rnd(-50,50),vy:rnd(-70,-20),life:rnd(.4,.7),col:pick(['#ffffff','#dff0ff']),sz:2,gy:e.y+4});}
  if(e.elite&&st&&st.lg&&st.lg.skull&&!isGuest())allySpawn(e.x,e.y);
  if(st&&st.lg&&!isGuest()){if(e.elite&&st.lg.sb2){const p=run.p,h=Math.ceil(p.max*.1);if(!p.down&&p.hp<p.max){p.hp=Math.min(p.max,p.hp+h);run.nums.push({x:p.x,y:p.y-10,txt:'+'+h,life:.8,col:'#8affa0'});}}
    if(st.lg.sb4&&e.bm&&run.t-e.bm<.3&&(run.allies||[]).filter(a=>!a.tw).length<3)allySpawn(e.x,e.y);}
  if(e.id==='phyl'){mfCall('jarBroken',e);}
  if(e.boss){run.boss=null;$('#bossbar').hidden=true;run.flashScr=.5;if(run.endless)enBossDown(e);else winRun();}
}
function hurtPlayer(d,src){
  const p=run.p;if(p.inv>0||run.over||run.dying||p.down||isGuest())return;
  if(window.__krypta&&window.__krypta.god)return;
  if(p.sh){p.sh=0;p.shT=0;p.inv=.6;run.fx.push({k:'shock',x:p.x,y:p.y-4,r:3,t:0,life:.35,max:22,col:'#e4dfcc'});sparks(p.x,p.y-4,8,'#e4dfcc');sfx('hit');return;}
  if(st.dodge&&Math.random()<st.dodge){p.inv=.3;run.nums.push({x:p.x,y:p.y-10,txt:_t('Úhyb'),life:.7,col:'#bfeaff'});sfx('ui');return;}
  const amt=Math.max(1,Math.round(d-st.armor));tmHit(src,amt);
  if(st.lg&&st.lg.mheart&&run.t-(run.mhT||-9)>2){run.mhT=run.t;explode(p.x,p.y,40,24+run.level*2);}
  if(st.af&&st.af.thorn&&run.t-(run.thT||-9)>1.5){run.thT=run.t;explode(p.x,p.y,38,st.af.thorn);}
  if(st.lg&&st.lg.wheart&&run.t-(run.whT||-9)>2){run.whT=run.t;for(const e of run.enemies)if(!e.dead&&!e.boss&&Math.hypot(e.x-p.x,e.y-p.y)<56)e.frz=Math.max(e.frz||0,1.6);run.fx.push({k:'ring',x:p.x,y:p.y,r:2,max:56,dmg:10+run.level,hit:new Set(),life:1,freeze:true,col:'#8af0ff'});}
  p.hp-=amt;p.inv=st.tal&&st.tal.k20?1.1:.6;p.flash=.15;run.shake=3;run.combo=run.hero&&run.hero.ach==='combo'?run.combo>>1:0;sfx('hurt');
  run.nums.push({x:p.x,y:p.y-8,txt:String(amt),life:.7,col:'#ff6a5a'});
  if(st.tr&&st.tr.d2&&!p.d2u&&p.hp>0&&p.hp<p.max*.3){p.d2u=1;const h=Math.ceil(p.max*.05*st.tr.d2);p.hp=Math.min(p.max,p.hp+h);run.nums.push({x:p.x,y:p.y-14,txt:'+'+h,life:1,col:'#8affa0'});toast(_t('Druhý dech!'),1400);sfx('level');}
  if(p.hp<=0){
    if(petRevive())return;
    if(st.lg&&st.lg.skyG&&!run.skyG){run.skyG=1;p.hp=Math.ceil(p.max*.4);p.inv=2.5;toast(_t('Štít hvězd!'),1800);sfx('level');run.fx.push({k:'shock',x:p.x,y:p.y-4,r:3,t:0,life:.6,max:70,col:'#6ab8ff'});run.eshots.length=0;return;}
    const rv=Math.min(3,(run.meta||save.meta).revive||0);if((rv>0||(st.lg&&st.lg.heart))&&!run.revived){run.revived=(run.revived|0)+1;p.hp=Math.ceil(p.max*(REV_HP[rv]||.5));p.inv=2.5;toast(_t('Druhá šance!'),1800);sfx('level');
      run.enemies.forEach(e=>{if(!e.boss&&Math.hypot(e.x-p.x,e.y-p.y)<90){e.kx+=(e.x-p.x)*5;e.ky+=(e.y-p.y)*5;}});
      run.eshots.length=0;}
    else if(run.pls)downPlayer(p);
    else startDeath();
  }
}
// the hero falls: hit-stop, the sprite bursts into pieces, red flash, the music ducks, then the world runs in slow motion until the end screen
function startDeath(){const p=run.p;p.hp=0;p.dead=1;run.dying=1.5;run.deathFx=1;run.hitstop=.14;run.shake=9;run.flashScr=.5;run.flashCol='#ff3a3a';
  const s=SPR.hero[run.heroId]||SPR.hero.knight;shatter(s.c,p.x,p.y-s.h/2,p.y+2,4,1.4);smokePuff(p.x,p.y-6,9,'#4a3a48',1.3);sparks(p.x,p.y-6,14,'#ff6a5a',0,0,140);
  sfx('death');duckMusic(-14,2.4);}
function addXP(v){if(isGuest())return;
  run.xp+=v*st.xpMul;
  while(run.xp>=run.need){run.xp-=run.need;run.level++;run.need=needXP(run.level);run.pending++;
    run.flashScr=Math.max(run.flashScr,.3);const p=run.p;for(let i=0;i<24;i++){const a=i/24*6.283;addP({x:p.x,y:p.y-4,vx:Math.cos(a)*95,vy:Math.sin(a)*95,life:.45,col:i%2?'#f6c744':'#fff6c8',sz:2,g:0});}}
}

/* ----- weapons ----- */
function nearest(n,maxD){
  const p=run.p,m2=maxD*maxD,out=[];
  for(const e of run.enemies){if(e.dead)continue;const d2=(e.x-p.x)**2+(e.y-p.y)**2;if(d2<m2)out.push([d2,e]);}
  out.sort((a,b)=>a[0]-b[0]);return out.slice(0,n).map(o=>o[1]);
}
function inView(e,m){const c=run.cam;return e.x>c.x-m&&e.x<c.x+VW+m&&e.y>c.y-m&&e.y<c.y+VH+m;}
function fire(s){s.hit=new Map();s.rehit=s.rehit||Infinity;s.rot=0;run.shots.push(s);}
// discrete weapons fire on 16th-note steps; offsets interleave them so the volley sounds like a groove
const W_OFF={bolt:0,arrows:2,lightning:0,fireball:8,axe:6,frost:0,aura:2,vortex:2,storm:0,meteor:8,blizzard:2,note:4,rang:10,echo:0,steam:8,halberd:0,whip:4,thunder:6,frostblade:0,arcane:2,flamering:4};
