 arrows:{fire(w,P){const p=run.p,t=nearest(1,170)[0],a0=t?Math.atan2(t.y-p.y,t.x-p.x):Math.atan2(p.face.y,p.face.x);sfx('shoot',1);
  for(let i=0;i<P.n;i++){const a=a0+(i-(P.n-1)/2)*.16;fire({x:p.x,y:p.y,vx:Math.cos(a)*200,vy:Math.sin(a)*200,dmg:P.dmg,r:2.5,pierce:P.pierce,life:1.1,kind:'arrow',kb:35});}}},
 frost:{fire(w,P){sfx('zap');const p=run.p;run.fx.push({k:'ring',x:p.x,y:p.y,r:2,max:P.rad,dmg:P.dmg,hit:new Set(),life:1});}},
