    if(run.pls){for(const q of players())if(!q.down&&s.life>0&&Math.hypot(s.x-q.x,s.y-q.y)<s.r+q.r){hurtP(q,s.dmg,s.src);if(s.slw)q.slw=Math.max(q.slw||0,s.slw);s.life=0;}}
