  const amt=Math.max(1,hazDm(6,.03)-Math.floor(st.armor/2));tmHit('haz',amt);p.hp-=amt;p.flash=.12;sfx('hurt');run.nums.push({x:p.x,y:p.y-8,txt:String(amt),life:.6,col:'#ff9a3c'});
