  const L=(x,y,r,a)=>{x+=ox;y+=oy;if(r<2||x<-r||y<-r||x>VW+r||y>VH+r)return;l.globalAlpha=Math.min(1,a);l.drawImage(LS,x-r,y-r,r*2,r*2);};
