  for(const pl of bm.pools){const x=pl.x+ox,y=pl.y+oy;if(x<-40||y<-40||x>VW+40||y>VH+40)continue;circ(g,x,y,pl.r,'#b8281a');circ(g,x,y,pl.r-3,'#f07a26');circ(g,x+Math.sin(t)*pl.r*.2,y,pl.r*.45,'#ffc24a',.85);}
  for(const q of bm.props){const s=q.spr,x=q.x+ox,y=q.y+oy;if(x+s.w<0||x-s.w>VW||y<-4||y-s.h>VH+4)continue;blit(g,s.c,s,x,y-s.h+1);}
