    circ(g,mx,my,11,'#f08a3c',.35);circ(g,mx,my,8,'#e8453c',.5);circ(g,mx,my,6,'#3a1e14');circ(g,mx-1,my-1,4,'#6a3a24');circ(g,mx-2,my-2,2,'#9a6a44');
