let sel={hero:'knight',map:'hrbitov'};
// a map opens after the previous one in its chapter; a chapter opens after the last map of the one before (older saves keep what they had)
function mapUnlocked(id){if(save.cheat||save.cleared[id]||(save.unl&&save.unl[id]))return true;const c=CH_OF[id];if(!c)return false;const i=c.maps.indexOf(id);
  if(i>0)return !!save.cleared[c.maps[i-1]];return c.i===0||!!save.cleared[CHAPTERS[c.i-1].maps.slice(-1)[0]];}
function nextMap(id){const c=CH_OF[id],i=c.maps.indexOf(id);return i<c.maps.length-1?c.maps[i+1]:CHAPTERS[c.i+1]?CHAPTERS[c.i+1].maps[0]:null;}
