const SET_IDS=Object.keys(SETS),SET_OF_CH={};for(const id of SET_IDS){SET_OF_CH[SETS[id].ch]=id;SETS[id].slots=SETS[id].slots||SET_SLOTS;}
// pieces that drop now (each set uses different slots; every 5th chapter has a six-piece set); older pieces in other slots still count
const setSlots=id=>SETS[id].slots,setMax=id=>SETS[id].slots.length;
const SET_DROP=.25,SET_PITY=3; // finale win: 25 % (+5 % per Nightmare tier), the 4th win without a piece always drops one
function setOwned(id){const o={};for(const it of save.inv||[])if(it.set===id)o[it.s]=1;return o;}
function setCount(h,id){const eq=(save.eq&&save.eq[h])||{};let n=0;for(const k of SLOT_IDS){const it=eq[k]&&itemById(eq[k]);if(it&&it.set===id)n++;}return n;}
// a set piece: a slot the player does not own yet if there is one, stats from the piece's own list at epic strength
// 08a: a set piece has its own rarity (by Nightmare tier) and is a random piece; colours follow the rarity like any item
const SET_RAR=[[0,50,35,13,2],[0,30,40,25,5],[0,15,40,35,10],[0,5,30,45,20]],SET_TRE=[0,0,65,30,5];
function rollW(w){let x=Math.random()*w.reduce((a,b)=>a+b,0);for(let i=0;i<w.length;i++){x-=w[i];if(x<0)return i;}return w.length-1;}
const setRarity=(nm,id)=>rollW(SET_RAR[clamp((nm|0)+(id&&SETS[id].six?1:0),0,3)]); // six-piece sets drop one Nightmare tier better
function makeSetItem(id,slot,r,q){const S=SETS[id];if(!slot||!S.pieces[slot]){const own=setOwned(id),miss=S.slots.filter(k=>!own[k]);slot=pick(miss.length&&Math.random()<.5?miss:S.slots);}if(r==null)r=setRarity(0,id);
  const st={};for(const k of S.pieces[slot].st)st[k]=rollStat(k,r,q!=null?q:.55+Math.random()*.45);return {u:newUid(),s:slot,r,lv:0,st,set:id};}
// gold : Úlomky ≈ 4 : 1 in upgrades (income ≈ 6 : 1, the rest goes to chests), Esence from +6 (see EKONOMIKA.md, tests/tools/econsim.py)
const SH_K=1.1,SH_CAP=6000,ES_FIRST=[25,35,50,70],ES_REP=[4,6,8,10],ES_FIN_DAY=3,EN_RATE=.4,EN_CAP=20,EN_T0=5,
  CH_LIMIT={iron:4,gold:2,tower:3,pet:3},RF_G=600,RF_SH=150,RF_GROW=1.25,RF_MAX=12;
const upF=(r,lv)=>{const c={gold:24*(lv+1)*(r+1),shard:6*(lv+1)*(r+1)};if(lv>=5)c.ess=(lv-4)*(r+1);return c;};
function investF(r,lv){const o={gold:0,shard:0,ess:0};for(let l=0;l<(lv||0);l++){const c=upF(r,l);for(const k in c)o[k]+=c[k];}return o;}
function refundF(r,lv){const v=investF(r,lv);return{gold:15*(r+1)*(r+1)+Math.floor(v.gold/2),shard:3*(r+1)+Math.floor(v.shard/2),ess:Math.floor(v.ess/2)};}
const canPay=c=>save.coins>=(c.gold||0)&&MAT_IDS.every(k=>!c[k]||(save.mats[k]||0)>=c[k]);
const payC=c=>{save.coins-=c.gold||0;for(const k of MAT_IDS)if(c[k])save.mats[k]-=c[k];};
const gainC=c=>{save.coins+=c.gold||0;for(const k of MAT_IDS)if(c[k])save.mats[k]=(save.mats[k]||0)+c[k];};
const rfCost=n=>{const k=Math.pow(RF_GROW,Math.min(n||0,RF_MAX));return{gold:Math.round(RF_G*k),shard:Math.round(RF_SH*k)};};
// daily limits of the bought chests (no endless chest buying with a pile of gold)
function chLeft(id){const d=today();if(!save.chD||save.chD.d!==d)save.chD={d,n:{}};const L=CH_LIMIT[id];return L==null?99:Math.max(0,L-(save.chD.n[id]||0));}
function chUse(id){chLeft(id);save.chD.n[id]=(save.chD.n[id]||0)+1;}
const ECON={
 chests:[{id:'wood',name:_t('Truhla dobrodruha'),cost:250,odds:[70,25,5,0,0]},
         {id:'iron',name:_t('Okovaná truhla'),cost:750,odds:[35,40,20,5,0],pity:{r:3,n:10}},
         {id:'gold',name:_t('Královská truhla'),cost:2000,odds:[0,30,45,20,5],pity:{r:4,n:30}}],
 upCost:it=>upF(it.r,it.lv||0),
 refund:it=>refundF(it.r,it.lv||0),
 heroCost:L=>{const c={gold:45*L+(L>=10?90*(L-9):0),shard:10*L};if(L>=10)c.ess=2+(L-10)+((L+1)%5===0?10:0);if(L>=HERO_ESS){const k=1.2+.025*(L-HERO_ESS);c.gold=Math.round(c.gold*k/10)*10;c.shard=Math.round(c.shard*k);c.ess=Math.round(c.ess*k*.8);}return c;},
 nmItem:[null,1,2,3]};
const HERO_MAX=40,HERO_ESS=20;
