 30:[{id:'wpn',ic:'*',t:_t('Mistr zbraně'),d:_t('Startovní zbraň dává +30 % základního poškození')},{id:'crit',ic:'eye',t:_t('Ostrostřelec'),d:_t('Kritický zásah +6 %')}],
