const heroTal=(h,t)=>{const c=save.htal&&save.htal[h];return c&&c[t]!=null?c[t]:-1;};
const heroPr=h=>(save.hpr&&save.hpr[h])||0;
const PR_PCT=.005;
function prCost(h){const p=heroPr(h);return{gold:6000+800*p,shard:400+40*p,ess:40+6*p};}
// what was spent on an item's upgrades so far (sum of upCost for levels 0..lv-1)
function upInvest(it){return investF(it.r,it.lv);}
