function guestApply(o){
  if(!run||!run.coop||CO.role!=='guest')return;
  const R=run,h2=v=>v/2;
  // keep the music in phase with the host
  const one=(NET.rtt||60)/2000,hostF=o.ms+(o.ma+one)/M.stepDur,mineF=M.step+M.acc/M.stepDur,d=hostF-mineF;
  if(Math.abs(d)>6){M.step=Math.round(hostF);M.acc=0;}else M.acc+=clamp(d*.2,-1,1)*M.stepDur*.5;
  R.t=o.tt;R.level=o.lvl;R.mat=o.mt||0;R.bw=!!o.bw;R.xp=o.xp;R.need=1;R.coins=o.c;R.kills=o.k;R.combo=o.cb;R.hs=o.hs;if(o.fs)R.flashScr=Math.max(R.flashScr,o.fs);
  const P=R.p,g=o.g;P.hp=g[2];P.max=g[3];P.down=!!g[7];P.rev=g[8];P.inv=g[9]?.3:0;if(g[10])P.flash=.12;R.gst=o.gs;st.speed=o.gs[0];st.max=o.gs[1];
  if(o.gp){P.x=o.gp[0];P.y=o.gp[1];}
  const m=R.mate,hh=o.h;m.tx=h2(hh[0]);m.ty=h2(hh[1]);if(!m.seen){m.x=m.tx;m.y=m.ty;m.seen=1;}m.hp=hh[2];m.max=hh[3];m.face.x=hh[4];m.face.y=hh[5];m.moving=!!hh[6];m.down=!!hh[7];m.rev=hh[8];m.inv=hh[9]?.3:0;if(hh[10])m.flash=.12;
  const wv=(src,dst)=>{for(const id in dst)if(!src[id])delete dst[id];for(const id in src){const a=src[id],w=dst[id]||(dst[id]={});w.lv=a[0];w.ang=a[1];w.r=a[2];w.pulse=a[3];w.mul=a[4];}};
  wv(o.gW,R.W);wv(o.hW,R.mateW);R.P=o.gP||{};
  const hk=JSON.stringify(Object.keys(R.W).map(k=>k+R.W[k].lv))+JSON.stringify(R.P);if(hk!==CO.hudKey){CO.hudKey=hk;buildItemsHud();}
  // enemies by id, smoothed towards the newest position
  const seen=new Set(),E=o.E;
  for(let i=0;i<E.length;i+=6){const id=E[i];seen.add(id);let e=R.eMap.get(id);
    if(!e){const ti=E[i+1];if(ti===-1){const bid=R.map.boss,d=BOSS_DEFS[bid],sp=SPR.boss[bid];e={id:bid,d,x:h2(E[i+2]),y:h2(E[i+3]),hp:1,max:1,r:d.r,spr:sp,w:sp.w,h:sp.h,flash:0,slowT:0,boss:true,elite:false,mode:0,par:false,hc:{},dead:false};}
      else e=makeEnemy(ETY[ti],h2(E[i+2]),h2(E[i+3]),!!(E[i+5]&1));R.eMap.set(id,e);R.enemies.push(e);}
    e.tx=h2(E[i+2]);e.ty=h2(E[i+3]);e.max=100;e.hp=E[i+4];const f=E[i+5];if(f&4)e.flash=.09;e.slowT=f&8?.2:0;e.frz=f&16?.2:0;e.mode=f&32?1:0;e.bur=f&64?1:0;if(f&128&&!e.want)e.want=WANT_OF[R.mapId];}
  for(const id of o.kd){const e=R.eMap.get(id);if(e)guestKillFx(e);}
  for(const [id,e] of R.eMap)if(!seen.has(id)){e.dead=true;R.eMap.delete(id);}
  R.enemies=R.enemies.filter(e=>!e.dead);
  R.boss=o.bo?R.eMap.get(o.bo)||null:null;$('#bossbar').hidden=!R.boss;if(R.boss&&!CO.bossShown){CO.bossShown=1;$('#bossName').textContent=R.boss.d.name;}
  // shots: dead reckoning between snapshots
  const ss=new Set(),S=o.S;
  for(let i=0;i<S.length;i+=7){const id=S[i];ss.add(id);let s=R.sMap.get(id);
    if(!s){s={kind:SKINDS[S[i+1]],x:h2(S[i+2]),y:h2(S[i+3]),vx:S[i+4],vy:S[i+5],rot:S[i+6]/10,life:2};R.sMap.set(id,s);R.shots.push(s);}
    else{s.x+=(h2(S[i+2])-s.x)*.6;s.y+=(h2(S[i+3])-s.y)*.6;s.vx=S[i+4];s.vy=S[i+5];s.rot=S[i+6]/10;}}
  for(const [id,s] of R.sMap)if(!ss.has(id)){s.dead=true;R.sMap.delete(id);}
  R.shots=R.shots.filter(s=>!s.dead);
  R.eshots=[];for(let i=0;i<o.ES.length;i+=2)R.eshots.push({x:h2(o.ES[i]),y:h2(o.ES[i+1]),r:3});
  R.gems=[];for(let i=0;i<o.G.length;i+=2)R.gems.push({x:h2(o.G[i]),y:h2(o.G[i+1])});
  R.items=[];for(let i=0;i<o.I.length;i+=3)R.items.push({x:h2(o.I[i]),y:h2(o.I[i+1]),k:IKINDS[o.I[i+2]]});
  R.towers=o.T.map((a,i)=>{const k=T_IDS[a[0]],old=R.towers[i];const t=old&&old.k===k&&Math.abs(old.x-h2(a[1]))<1?old:{isTower:true,k,spr:SPR.tower[k],show:0};
    Object.assign(t,{x:h2(a[1]),y:h2(a[2]),lv:a[3],hp:a[4],max:a[5],kick:a[6],flash:a[7]?.1:0,dwA:!!a[8],dwk:a[8]?(a[8]-1)/8:0});return t;});
  if(R.crystal&&o.cr){R.crystal.hp=o.cr[0];R.crystal.max=o.cr[1];if(o.cr[2])R.crystal.flash=.12;}
  if(o.ca){R.carts=o.ca.map(s=>{const q=railPos(s);return{s,x:q.x,y:q.y};});}
  R.curse=o.cu?1:0;if(o.mf)mfCall('apply',o.mf);R.allies=[];if(o.al)for(let i=0;i<o.al.length;i+=3)R.allies.push({isAlly:true,x:h2(o.al[i]),y:h2(o.al[i+1]),t:o.al[i+2],face:1});
  {const old=R.gpets||[],np=[];if(o.pt)for(let i=0,j=0;i<o.pt.length;i+=5,j++){const k=PET_IDS[o.pt[i]];if(!k)continue;const q=old[j]&&old[j].k===k?old[j]:{isPet:true,k,x:h2(o.pt[i+1]),y:h2(o.pt[i+2]),t:0,anim:0,face:1};
      q.tx=h2(o.pt[i+1]);q.ty=h2(o.pt[i+2]);q.face=o.pt[i+3];q.bit=o.pt[i+4]&1?.12:0;q.rd=o.pt[i+4]&2?1:0;np.push(q);}R.gpets=np;
    R.pfire=(o.pf||[]).map(a=>({x:h2(a[0]),y:h2(a[1]),r:a[2],life:a[3],max:a[4],seed:a[5],t:0}));}
  for(const f of o.fx){f.hit=new Set();R.fx.push(f);if(f.k==='boom')sfx('boom');else if(f.k==='bolt'||f.k==='arc')sfx('zap');}
  for(const n of o.n)if(R.nums.length<40)R.nums.push({x:h2(n[0]),y:h2(n[1]),txt:n[2],col:n[3],big:!!n[4],life:n[4]?.75:.6,t:0});
  if(o.n.length)sfx('hit');
}
function guestKillFx(e){const R=run;sfx('kill');const pal=e.d.pal||{},pa=pal.a||'#c869e0',cols=[pa,pal.b||mixHex(pa,SHADOW_HUE,.4),pal.c||mixHex(pa,LIGHT_HUE,.4)];
  const n=e.boss?36:e.elite?16:8,gy=e.y+e.h/2-4;if(R.parts.length<420)for(let i=0;i<n;i++)R.parts.push({x:e.x+rnd(-3,3),y:e.y+rnd(-3,3),vx:rnd(-55,55),vy:rnd(-95,-25),life:rnd(.5,.85),col:pick(cols),sz:e.boss?3:(Math.random()<.35?1:2),gy});
  R.fx.push({k:'pop',x:e.x,y:e.y,r:2,max:e.r*2+5,life:.16,t:0,hit:new Set()});}
function guestUpdate(dt){
  const R=run,p=R.p,sz=R.map.size;R.t+=dt;
  if(R.hs==='play'){const inp=getInput();let mx=inp.x,my=inp.y;const mm=Math.hypot(mx,my);if(mm>1){mx/=mm;my/=mm;}if(R.curse){mx=-mx;my=-my;}
    p.moving=mm>.05;if(p.moving){p.face.x=mx/Math.max(mm,.001);p.face.y=my/Math.max(mm,.001);p.anim+=dt*10;}
    const spd=st.speed*(p.down?.55:1);p.x=clamp(p.x+mx*spd*dt,14,sz-14);p.y=clamp(p.y+my*spd*dt,14,sz-14);mfCall('move',p,dt);}else p.moving=false;
  p.inv=Math.max(0,p.inv-dt);p.flash=Math.max(0,p.flash-dt);
  const m=R.mate;if(m.tx!==undefined){const k=Math.min(1,dt*14);m.x+=(m.tx-m.x)*k;m.y+=(m.ty-m.y)*k;}
  for(const P of R.gpets||[]){P.t+=dt;if(P.tx!==undefined){const k=Math.min(1,dt*12),d=Math.hypot(P.tx-P.x,P.ty-P.y);if(d>120){P.x=P.tx;P.y=P.ty;}else{P.x+=(P.tx-P.x)*k;P.y+=(P.ty-P.y)*k;}if(d>1)P.anim+=dt*10;}}m.flash=Math.max(0,m.flash-dt);m.inv=Math.max(0,m.inv-dt);
  const k=Math.min(1,dt*12);
  for(const e of R.enemies){if(e.tx!==undefined){e.x+=(e.tx-e.x)*k;e.y+=(e.ty-e.y)*k;}e.flash=Math.max(0,e.flash-dt);}
  for(const s of R.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;}
  for(const t of R.towers)t.show=Math.max(0,(t.show||0)-dt);
  if(R.crystal)R.crystal.flash=Math.max(0,R.crystal.flash-dt);
  updateFx(dt);updateAmbient(dt);mfCall('gupdate',dt);
  let nt=null,nd=26;for(const t of R.towers){const d=Math.hypot(t.x-p.x,t.y-p.y);if(d<nd){nd=d;nt=t;}}R.nearTower=nt;
  const c=R.crystal;R.nearCrystal=c&&Math.hypot(c.x-p.x,c.y-p.y)<30&&c.hp<c.max?c:null;
  R.shake=Math.max(0,R.shake-dt*14);
  R.cam.x=clamp(p.x-VW/2,0,Math.max(0,sz-VW));R.cam.y=clamp(p.y-VH/2,0,Math.max(0,sz-VH));
}
NET.h.s=o=>guestApply(o);
NET.h.toast=o=>toast(o.m,2400);
NET.h.note=o=>note(o.m);
NET.h.lvl=o=>{if(CO.role!=='guest'||!run)return;CO.cards=o.cards;
  $('#luTitle').textContent=o.chest?_t('Poklad!'):_t('Nová úroveň!');const list=$('#luList');list.innerHTML='';
  o.cards.forEach((i,idx)=>{const b=luCard(i,idx,false);
    b.addEventListener('click',()=>{if(state!=='levelup')return;sfx('ui');if(i.fuse&&i.f){startFuse(i.f,idx);}else{netSend({t:'pick',i:idx});coWait();}});list.appendChild(b);});
  sfx('level');setState('levelup');luPaint();};
NET.h.lvlx=()=>{if(state==='levelup'||state==='wait')setState('play');};
NET.h.resume=()=>{if(CO.role==='guest'&&run&&!run.over&&(state==='wait'||state==='levelup'))setState('play');};
NET.h.end=o=>{if(CO.role==='guest'&&run&&!run.over){run.crystalDead=o.cd;if(o.tt!==undefined){run.t=o.tt;run.coins=o.c;run.spent=o.sp||0;run.mat=o.mt;run.kills=o.k;run.level=o.lv;}run.qcR=o.q||null;finish(!!o.won);setTimeout(()=>{netClose();CO.on=false;CO.role=null;},1500);}};
function coWait(){$('#waitTxt').textContent=_t('Kamarád ještě vybírá…');setState('wait');}

/* ----- shared rendering helpers ----- */
function coMate(){return run?(run.pls?run.pls[1].p:run.mate||null):null;}
function plWeapons(){const out=[[run.p,run.W]];if(run.pls)out.push([run.pls[1].p,run.pls[1].W]);else if(run.mate)out.push([run.mate,run.mateW]);return out.filter(a=>!a[0].down&&!a[0].dead);}
function drawMate(g,u,ox,oy){
  const s=SPR.hero[u.heroId]||SPR.hero.knight,x=RZ(u.x+ox),y=RZ(u.y+oy);
  const ph=u.moving?(Math.floor(M.beatPos*2)&1):(((M.beatPos%1)+1)%1<.14?1:0),img=ph?(u.flash>0?s.f2:s.c2):(u.flash>0?s.f:s.c),bob=u.moving&&!ph?-1:0;
  shadow(g,x,y+s.h/2-4,10);g.globalAlpha=u.down?.45:(u.inv>0&&Math.floor(run.t*20)%2===0?.5:1);blit(g,img,s,x,y-s.h/2+bob-1);g.globalAlpha=1;
  // friend marker and health
  g.fillStyle='#14101c';g.fillRect(x-2,y-s.h/2-7,5,4);g.fillStyle='#7cf0a0';g.fillRect(x-1,y-s.h/2-6,3,2);
  if(!u.down&&u.hp<u.max){const bw=14;g.fillStyle='#000';g.fillRect(x-bw/2-1,y+s.h/2-1,bw+2,3);g.fillStyle='#5cc45c';g.fillRect(x-bw/2,y+s.h/2,Math.round(bw*clamp(u.hp/u.max,0,1)),1);}
}
function drawCoop(g,ox,oy){
  const P=players();if(P.length<2)return;const a=P[0],b=P[1];
  // downed heroes: a revive ring that fills on every beat
  for(const q of P){if(!q.down)continue;const x=q.x+ox,y=q.y+oy;ringPix(g,x,y,22,'#7cf0a0',.35+M.pulse*.3);
    for(let i=0;i<4;i++){const an=-1.57+i*1.57;g.fillStyle=i<(q.rev||0)?'#7cf0a0':'#2a3a30';g.fillRect(RZ(x+Math.cos(an)*22)-1,RZ(y+Math.sin(an)*22)-1,3,3);}}
  if(a.down||b.down)return;
  const d=Math.hypot(b.x-a.x,b.y-a.y),k=bondStr(d,run.bw);if(k<=0)return;
  const gold=k>=.99,col=gold?'#f6c744':'#7fcaff',hi=gold?'#fff6c8':'#e0f4ff',n=Math.max(2,Math.ceil(d/2)),pul=M.pulse;
  for(let i=0;i<=n;i++){const t=i/n,w=Math.sin(t*3.14159)*Math.sin(run.t*9+t*14)*(1.2+pul*2),nx=-(b.y-a.y)/(d||1),ny=(b.x-a.x)/(d||1);
    const x=a.x+(b.x-a.x)*t+nx*w+ox,y=a.y-4+(b.y-a.y)*t+ny*w+oy;g.globalAlpha=(.25+k*.25)*(.7+pul*.3);g.fillStyle=col;g.fillRect(RZ(x)-1,RZ(y)-1,gold?3:2,gold?3:2);
    g.globalAlpha=(.45+k*.45)*(.75+pul*.25);g.fillStyle=pul>.4&&i%2===0?hi:col;g.fillRect(RZ(x),RZ(y),1,1);}
  g.globalAlpha=1;
}
function drawMateArrow(g,ox,oy){const m=coMate();if(!m)return;const cx=m.x+ox,cy=m.y+oy;if(cx>2&&cy>2&&cx<VW-2&&cy<VH-2)return;
  const mx=Math.round(clamp(cx,10,VW-10)),my=Math.round(clamp(cy,42,VH-48));g.fillStyle='#14101c';g.fillRect(mx-6,my-6,13,13);
  g.fillStyle=m.down?'#e8453c':'#7cf0a0';g.fillRect(mx-5,my-5,11,11);const s=SPR.hero[m.heroId];if(s)g.drawImage(s.c,mx-4,my-5,8,8*s.h/s.w);}

/* ============ news (what's new popup), install to home screen, result sharing ============ */
